<?php
declare(strict_types=1);
require __DIR__.'/../hosting/bkpandey-private/core.php';
bp_session();
$checks=0;
function verify(bool $condition,string $message): void {global $checks;$checks++;if(!$condition)throw new RuntimeException($message);}
function denied(callable $fn,string $message): void {try{$fn();}catch(Throwable $e){verify(true,$message);return;}verify(false,$message);}
$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
$db->exec('CREATE TABLE bp_blog_categories(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE);CREATE TABLE bp_blog_posts(id INTEGER PRIMARY KEY AUTOINCREMENT,category_id INTEGER,slug TEXT UNIQUE,title TEXT,excerpt TEXT,body TEXT,status TEXT,source_url TEXT,origin TEXT,published_at TEXT,created_at TEXT,updated_at TEXT,version INTEGER DEFAULT 1,pdf_display TEXT DEFAULT \'file\',slider_interval INTEGER DEFAULT 6);CREATE TABLE bp_blog_admins(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT UNIQUE,password_hash TEXT);CREATE TABLE bp_blog_login_limits(attempt_key TEXT PRIMARY KEY,attempts INTEGER,window_started INTEGER);');
$db->exec("INSERT INTO bp_blog_categories(name) VALUES ('Payments')");
$input=['category_id'=>1,'slug'=>'safe-payment-test','title'=>"Payment ' OR 1=1 --",'excerpt'=>'A useful article summary for the test.','body'=>"## A heading\n<script>alert('x')</script>\n- A list item\nAn article with enough text for validation.",'status'=>'draft','source_url'=>'https://www.linkedin.com/in/brajkishorpandey/'];
$id=bp_save_post($db,$input);verify($id>0,'Create article');
verify(bp_post($db,$input['slug'])===null,'Draft must not be public');
$stored=bp_post($db,$input['slug'],false);verify($stored['title']===$input['title'],'SQL-like title remains data');
verify(!str_contains(bp_markdown($stored['body']),'<script>'),'Raw HTML is escaped');
verify(str_contains(bp_markdown($stored['body']),'&lt;script&gt;'),'Escaped source preserved');
$input['status']='published';bp_save_post($db,$input,$id,1);verify(bp_post($db,$input['slug'])!==null,'Published article is visible');
denied(fn()=>bp_save_post($db,$input,$id,1),'Stale version cannot overwrite current article');
$input['status']='archived';bp_save_post($db,$input,$id,2);verify(bp_post($db,$input['slug'])===null,'Archived article is hidden');
denied(fn()=>bp_source_url('javascript:alert(1)'),'Reject script source URL');
denied(fn()=>bp_validate_post(array_merge($input,['slug'=>'../private'])),'Reject path traversal slug');
denied(fn()=>bp_save_post($db,array_merge($input,['slug'=>'invalid-category','category_id'=>999])),'Reject nonexistent category');
$token=bp_csrf();bp_check_csrf($token);verify(true,'Accept matching CSRF token');
denied(fn()=>bp_check_csrf('wrong'),'Reject invalid CSRF token');
$testPassword='only-a-test-password-943287';$q=$db->prepare('INSERT INTO bp_blog_admins(email,password_hash) VALUES (?,?)');$q->execute(['owner@example.test',password_hash($testPassword,PASSWORD_DEFAULT)]);
verify(bp_try_login($db,'owner@example.test',$testPassword,'test-ip'),'Correct owner can sign in');
for($i=0;$i<6;$i++)verify(!bp_try_login($db,'owner@example.test','incorrect','other-test-ip'),'Incorrect password rejected');
verify(!bp_try_login($db,'owner@example.test',$testPassword,'other-test-ip'),'Rate limit also blocks a correct password during lockout');
$db->exec('UPDATE bp_blog_login_limits SET window_started=0');verify(bp_try_login($db,'owner@example.test',$testPassword,'other-test-ip'),'Sign-in resumes after rate window');
$temp=tempnam(sys_get_temp_dir(),'bp-upload');file_put_contents($temp,'<?php echo "unsafe";');
denied(fn()=>bp_check_upload($temp,'script.php',filesize($temp)),'Reject executable attachment');unlink($temp);
$pdf=__DIR__.'/../dist/assets/documents/Brajkishor_Pandey_Resume.pdf';$info=bp_check_upload($pdf,'resume.pdf',filesize($pdf));verify($info['mime']==='application/pdf','Accept a valid PDF');
denied(fn()=>bp_check_upload($pdf,'resume.php',filesize($pdf)),'Reject mismatched filename extension');
denied(fn()=>bp_check_upload($pdf,'resume.pdf',11*1024*1024),'Reject oversized attachment');
require __DIR__.'/../hosting/bkpandey-private/seed-import.php';
$db->exec('CREATE TABLE bp_blog_assets(id INTEGER PRIMARY KEY AUTOINCREMENT,original_name TEXT,public_path TEXT,storage_key TEXT,size_bytes INTEGER DEFAULT 0,mime_type TEXT);CREATE TABLE bp_blog_post_assets(post_id INTEGER,asset_id INTEGER,is_cover INTEGER,sort_order INTEGER DEFAULT 0,PRIMARY KEY(post_id,asset_id));');
$seed=json_decode(file_get_contents(__DIR__.'/../hosting/bkpandey-private/seed.json'),true,512,JSON_THROW_ON_ERROR);
verify(bp_import_initial_articles($db)===count($seed),'Import all initial articles');
verify(bp_import_initial_articles($db)===0,'Repeated import is idempotent');
verify((int)$db->query('SELECT COUNT(*) FROM bp_blog_assets')->fetchColumn()===array_sum(array_map(fn($p)=>$p['attachment']?2:(!empty($p['cover_image'])?1:0),$seed)),'Import the release PDFs and cover images');
$db->exec("UPDATE bp_blog_posts SET title='Owner edited this' WHERE slug='payout-routing-total-cost'");
bp_import_initial_articles($db);
verify($db->query("SELECT title FROM bp_blog_posts WHERE slug='payout-routing-total-cost'")->fetchColumn()==='Owner edited this','Import preserves edited articles');
$db->exec('CREATE TABLE bp_site_settings(setting_key TEXT PRIMARY KEY,setting_value TEXT,updated_at TEXT)');
verify(bp_public_asset($db,2147483647)===null,'Unknown media ID remains absent');
verify(bp_public_asset($db,1)!==null,'Published article attachment is public');
$db->exec("INSERT INTO bp_blog_assets(id,original_name,mime_type) VALUES (999,'private-fixture.pdf','application/pdf')");
$q=$db->prepare('INSERT INTO bp_blog_post_assets(post_id,asset_id,is_cover) VALUES (?,999,0)');$q->execute([$id]);
verify(bp_public_asset($db,999)===null,'Archived article attachment stays private');
bp_set_site_value($db,'resume_asset','999');
verify((int)bp_public_asset($db,999)['id']===999,'Explicit website resume is publicly readable');
$db->exec("DELETE FROM bp_site_settings WHERE setting_key='resume_asset'");
verify(bp_public_asset($db,999)===null,'Removing a public website alias revokes access');
verify(bp_byte_range('bytes=0-99',1000)===[0,99],'Bounded byte range');
verify(bp_byte_range('bytes=-50',1000)===[950,999],'Suffix byte range');
verify(bp_byte_range('bytes=900-',1000)===[900,999],'Open byte range');
verify(bp_byte_range('bytes=900-4000',1000)===[900,999],'Clamp end to file size');
denied(fn()=>bp_byte_range('bytes=1000-',1000),'Reject range beyond file');
denied(fn()=>bp_byte_range('bytes=0-1,4-5',1000),'Reject unsupported multiple ranges');
$produced=0;$key='test-'.bin2hex(random_bytes(8));
$compute=function()use(&$produced){return ++$produced;};
verify(bp_cached($key,$compute)===1 && bp_cached($key,$compute)===1,'Warm cache avoids repeated computation');
bp_cache_invalidate();verify(bp_cached($key,$compute)===2,'Cache invalidates immediately');
bp_set_site_value($db,'hero_title','A clear headline');verify(bp_site_values($db)['hero_title']==='A clear headline','Website settings persist');
denied(fn()=>bp_set_site_value($db,'db_password','invalid'),'Settings reject credential keys');
$catalog=bp_public_catalog($db);verify(count($catalog)===count($seed),'Catalog excludes archived article');
$withPDF=array_values(array_filter($catalog,fn($p)=>count($p['assets'])>0))[0];
verify(str_contains(bp_media_markup($withPDF['assets'],'carousel'),'data-pdf-carousel'),'PDF carousel markup');
verify(!str_contains(bp_media_markup($withPDF['assets'],'file'),'data-pdf-carousel'),'PDF download mode does not load carousel');
verify(str_contains(bp_media_markup(array_merge($withPDF['assets'],$withPDF['assets'])),'data-image-carousel'),'Multiple images become slideshow');
verify(bp_post($db,'payout-routing-total-cost')['pdf_display']==='carousel','Imported PDF uses carousel mode');
$input['status']='published';$input['pdf_display']='carousel';$input['slider_interval']=8;bp_save_post($db,$input,$id,3);
verify((int)bp_post($db,$input['slug'])['slider_interval']===8,'Persist slider duration');
denied(fn()=>bp_validate_post(array_merge($input,['pdf_display'=>'script'])),'Reject invalid PDF mode');
$defaults=[];foreach(bp_site_fields() as $key=>$field)$defaults[$key]=$field[1];
verify(bp_validate_site_values($defaults)['contact_email']==='brajkishorpandey@gmail.com','Accept all editable site defaults');
denied(fn()=>bp_validate_site_values(array_merge($defaults,['contact_email'=>'x@evil\r\nBcc: stolen@example.test'])),'Reject header injection email');
denied(fn()=>bp_validate_site_values(array_merge($defaults,['contact_linkedin'=>'javascript:alert(1)'])),'Reject script contact link');
denied(fn()=>bp_validate_site_values(array_merge($defaults,['contact_whatsapp'=>'123+script'])),'Reject invalid WhatsApp target');
$defaults['contact_title']='<script>alert(1)</script>';
$html=bp_apply_site_html('<section class="section contact"><h2>Contact</h2></section><p data-resume-summary>Old</p>',$defaults);
verify(!str_contains($html,'<script>'),'Escape editable contact text');
verify(str_contains($html,$defaults['resume_summary']),'Render editable brief resume');
denied(fn()=>bp_check_upload($pdf,'resume.php.pdf',filesize($pdf)),'Reject double script extension');
verify(bp_asset_url(['id'=>9,'public_path'=>null],true)==='/api/media/9/view','Media API URL has no script suffix');
denied(fn()=>bp_change_password($db,1,'incorrect','a-test-only-new-password-392','a-test-only-new-password-392'),'Password change needs current password');
denied(fn()=>bp_change_password($db,1,$testPassword,'short','short'),'Reject short new password');
denied(fn()=>bp_change_password($db,1,$testPassword,'a-test-only-new-password-392','different'),'Reject password confirmation mismatch');
$oldStamp=$_SESSION['auth_stamp'];bp_change_password($db,1,$testPassword,'a-test-only-new-password-392','a-test-only-new-password-392');
$newHash=$db->query('SELECT password_hash FROM bp_blog_admins WHERE id=1')->fetchColumn();
verify(password_verify('a-test-only-new-password-392',$newHash),'Store changed password as a verifiable hash');
verify(!hash_equals($oldStamp,hash('sha256',$newHash)),'Existing session stamps become invalid after password change');
$_GET = ['q'=>'payout-routing-total-cost','status'=>'published'];
ob_start();
require __DIR__.'/../hosting/bkpandey-private/article-list.php';
$articleList = ob_get_clean();
verify(str_contains($articleList,'Owner edited this') && str_contains($articleList,'Showing 1–1 of 1 articles'), 'Find a published article by slug');
$_GET = ['q'=>'%','status'=>'published'];
ob_start();
require __DIR__.'/../hosting/bkpandey-private/article-list.php';
verify(str_contains(ob_get_clean(),'No articles match these filters.'), 'Treat SQL wildcard characters as literal search text');
$_GET = ['status'=>'published','page'=>'2'];
ob_start();
require __DIR__.'/../hosting/bkpandey-private/article-list.php';
$articleList = ob_get_clean();
verify(str_contains($articleList,'Page 2 of 3') && str_contains($articleList,'status=published&amp;page=1'), 'Keep status while paging the articles');
unset($_GET);
echo $checks.' blog behavior and security checks passed.'.PHP_EOL;
